-- ═══════════════════════════════════════════════════════════════════════════
-- v117 · ISO/IEC 27701 · GESTIÓN DE LA PRIVACIDAD DE LA INFORMACIÓN
--
-- Va detrás de la v116. Añade la norma al catálogo de Órbita:
--
--   · `normas_catalogo`: ISO 27701, nivel J2, 55 h de apoyo. Es la extensión
--     de privacidad de ISO 27001/27002 (Sistema de Gestión de la Información
--     de Privacidad, SGIC): exige un SGSI en el que apoyarse, así que en la
--     app va marcada como complementaria de 27001 (`solapeCon`) y cuesta menos
--     cuando se contrata junto a ella.
--   · `tareas_catalogo`: 20 tareas por modelo (Apoyo, Relación, Implicación,
--     Compromiso, Implantación). Las del mapa de procesos común (PE1–PE3, PA1,
--     PA3, PA5, PA6) llevan en la descripción lo que 27701 añade al SGSI; las
--     cinco de PA19 «Gestión de la privacidad» son las propias de la norma:
--     registro de tratamientos, EIPD, derechos, brechas y transferencias.
--   · `codigo_proyecto`: la abreviatura «277» para el código de proyecto
--     (CLIE-2026-REL-27-277). Sin esto salía igual por el caso por defecto,
--     pero conviene que esté explícita como las demás.
--
-- Horas por modelo: Apoyo y Relación 92 h · Implicación 116 h · Compromiso
-- 148 h · Implantación 55,2 h. Unas dos terceras partes de ISO 27001, que es
-- la proporción habitual de la extensión sobre la norma base.
-- ═══════════════════════════════════════════════════════════════════════════

on conflict (id) do update
  set nombre = excluded.nombre, descripcion = excluded.descripcion,
      nivel = excluded.nivel, h_apoyo = excluded.h_apoyo, activa = excluded.activa;

-- Se relanza sin duplicar: si ya hubiera tareas de la 27701, se sustituyen.
delete from public.tareas_catalogo where norma_id = '27701';


-- ── Abreviatura en el código de proyecto ───────────────────────────────────
create or replace function public.codigo_proyecto(p_cliente text, p_anio integer, p_modelo text, p_normas text[])
returns text language plpgsql immutable as $$
declare serv text; ns text[] := '{}'; n text; corta text;
begin
  serv := case p_modelo
    when 'Implantación' then 'IMP' when 'Apoyo' then 'APO'
    when 'Relación' then 'REL' when 'Implicación' then 'IML'
    when 'Compromiso' then 'CMP' else 'XXX' end;

  foreach n in array coalesce(p_normas, '{}') loop
    corta := case n
      when '9001' then '9'   when '14001' then '14' when '27001' then '27'
      when '27701' then '277'
      when '45001' then '45' when '42001' then '42' when '56001' then '56'
      when '21001' then '21' when '9004' then '9004'
      when '93200' then '932' when '158101' then '158' when '66181' then '661'
      when 'igualdad' then 'IG'  when 'igualdad-seg' then 'IGS'
      when 'diversidad' then 'DV' when 'diversidad-seg' then 'DVS'
      when 'madridexcelente' then 'ME'
      else upper(substr(n, 1, 3)) end;
    ns := ns || corta;
  end loop;

  return public.sigla_cliente(p_cliente) || '-' || coalesce(p_anio, extract(year from current_date)::int)::text
       || '-' || serv || case when array_length(ns,1) > 0 then '-' || array_to_string(ns, '-') else '' end;
end $$;

notify pgrst, 'reload schema';

-- ── Comprobación ───────────────────────────────────────────────────────────
select 'v117 aplicada' as ok;
select modelo, count(*) as tareas, sum(horas_base) as horas
  from public.tareas_catalogo where norma_id = '27701' group by modelo order by modelo;   -- 5 filas × 20 tareas
select public.codigo_proyecto('Empresa Ejemplo', 2026, 'Relación', array['27001','27701']) as codigo;  -- EMEJ-2026-REL-27-277
